WITH long_format AS (SELECT id, status, measure, val FROM (SELECT id, status, shipping_fee, amount, discount FROM orders) src UNPIVOT (val FOR measure IN (shipping_fee AS SHIPPING_FEE_VAL, amount AS AMOUNT_VAL, discount)) long_rows) SELECT status, CASE WHEN val >= 74 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, COUNT(CASE WHEN measure = 'SHIPPING_FEE_VAL' THEN 1 END) AS shipping_fee_val_count, ROUND(AVG(val), 2) AS avg_val, COUNT_IF(measure = 'SHIPPING_FEE_VAL') AS shipping_fee_val_events FROM long_format GROUP BY status, CASE WHEN val >= 74 THEN 'LARGE' ELSE 'SMALL' END HAVING shipping_fee_val_events > 1 ORDER BY shipping_fee_val_count DESC NULLS FIRST;
